import {createDatabase,sql} from '/app/apps/backend/dist/database.js';
import {loadConfig} from '/app/apps/backend/dist/config.js';
const c=loadConfig(process.env); if(c.nodeEnv!=='qa')throw Error('QA_ONLY');
const db=createDatabase(c);
try {console.log(JSON.stringify(await db.transaction().execute(async tx=>{
 await sql`SET TRANSACTION READ ONLY`.execute(tx);
 const identity=(await sql`SELECT current_database() AS database,current_setting('server_version_num')::int/10000 AS postgresql_major,
 host(inet_server_addr()) AS host,CURRENT_TIMESTAMP AS observed_at`.execute(tx)).rows[0];
 if(identity.database!=='tcdx-grc'||identity.host!=='192.168.2.40'||identity.postgresql_major!==16)throw Error('QA_IDENTITY_REQUIRED');
 const migrations=(await sql`SELECT migration_id,filename,content_sha256,outcome FROM platform.schema_migrations ORDER BY migration_id`.execute(tx)).rows;
 const registry=(await sql`SELECT d.lifecycle_transition_definition_id::text AS id,d.entity_type,d.from_state,d.command_code,d.to_state,
 d.precondition_policy_ref,p.permission_code,d.sod_policy_ref,d.audit_event_code,d.notification_policy_ref,d.recalculation_policy_ref,
 d.idempotency_semantics,d.concurrency_semantics,d.system_actor_allowed,d.lifecycle_state,
 (SELECT jsonb_agg(s.scope_kind ORDER BY s.scope_kind) FROM ops_audit.lifecycle_transition_scopes s WHERE s.lifecycle_transition_definition_id=d.lifecycle_transition_definition_id) AS scopes,
 (SELECT count(*)::int FROM ops_audit.lifecycle_transition_side_effects e WHERE e.lifecycle_transition_definition_id=d.lifecycle_transition_definition_id) AS effects,
 (SELECT count(*)::int FROM ops_audit.audit_events a WHERE a.aggregate_id=d.lifecycle_transition_definition_id AND a.command_code='step6a3C04wLifecyclePublication'
  AND a.event_code='audit.platform.lifecycle_transition.publish.v1' AND a.actor_service_principal_id=d.created_by_service_principal_id
  AND a.outcome='success' AND a.after_payload->>'publication_manifest_sha256'='e7f30ded29f213fa33a8648466b5c7bbfcc6bb520e6cdf2b11968a41d9f6e944') AS audits
 FROM ops_audit.lifecycle_transition_definitions d JOIN iam.permissions p USING(permission_id)
 WHERE d.command_code IN ('retention_policy.submit_for_review','retention_policy_applicability.submit_for_review','retention_policy_applicability.review',
 'retention_policy_applicability.approve','retention_policy_applicability.publish') ORDER BY d.command_code`.execute(tx)).rows;
 const safety=(await sql`SELECT (SELECT count(*)::int FROM pg_constraint WHERE contype='f' AND NOT convalidated) AS unvalidated_foreign_keys,
 (SELECT count(*)::int FROM pg_constraint WHERE contype='f' AND confdeltype='c') AS forbidden_delete_cascades`.execute(tx)).rows[0];
 const protected_history=(await sql`SELECT e.evidence_version_id,e.effective_from,e.lifecycle_state,e.row_version FROM evidence.evidence_versions e
 WHERE evidence_version_id='01a118e4-ba56-76e7-aa44-d03594933d9c'`.execute(tx)).rows;
 return {identity,migrations,registry,safety,protected_history,transaction:'READ_ONLY'};
})));}finally{await db.destroy();}
